# ---------- BANCO DE DADOS ----------
import sqlite3

def conectar_banco():
    conn = sqlite3.connect("modo_caso.db")
    conn.row_factory = sqlite3.Row
    return conn
def criar_tabelas():
    conn = conectar_banco()
    cursor = conn.cursor()

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS turmas (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            escola TEXT NOT NULL,
            serie TEXT NOT NULL,
            turma TEXT NOT NULL,
            turno TEXT NOT NULL,
            caso TEXT NOT NULL,
            quantidade_equipes INTEGER NOT NULL
        )
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS equipes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            turma_id INTEGER NOT NULL,
            nome TEXT NOT NULL,
            codigo TEXT NOT NULL UNIQUE,
            FOREIGN KEY (turma_id) REFERENCES turmas(id)
        )
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS progresso (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            equipe_codigo TEXT NOT NULL,
            etapa INTEGER NOT NULL,
            concluido INTEGER DEFAULT 0
        )
    """)

    conn.commit()
    conn.close()

criar_tabelas()
def salvar_progresso(codigo_equipe, etapa, concluido=0):
    conn = conectar_banco()
    cursor = conn.cursor()

    cursor.execute(
        "SELECT id FROM progresso WHERE equipe_codigo = ?",
        (codigo_equipe,)
    )

    registro = cursor.fetchone()

    if registro:
        cursor.execute(
            """
            UPDATE progresso
            SET etapa = ?, concluido = ?
            WHERE equipe_codigo = ?
            """,
            (etapa, concluido, codigo_equipe)
        )
    else:
        cursor.execute(
            """
            INSERT INTO progresso (equipe_codigo, etapa, concluido)
            VALUES (?, ?, ?)
            """,
            (codigo_equipe, etapa, concluido)
        )

    conn.commit()
    conn.close()
    

